void setup() {
  Serial.begin(115200);
  Serial.println("Send a number (e.g., 123) or a letter (e.g., abc):");
}

void loop() {
  // Check if data is available in the buffer
  if (Serial.available() > 0) {

    // Look at the character at the front of the line without removing it
    char nextChar = Serial.peek(); 

    // Check if the peeked character is a number (0 through 9)
    if (nextChar >= '0' && nextChar <= '9') {
      // Because it's a number, use parseInt to read the whole number
      int number = Serial.parseInt(); 
      Serial.print("Found a number: ");
      Serial.println(number);
    } 
    // If it's not a number, handle it as text
    else {
      // Remove it from the buffer using standard read()
      char textChar = Serial.read(); 

      // Ignore newline or carriage return characters from the serial monitor
      if (textChar != '\n' && textChar != '\r') {
        Serial.print("Found text: ");
        Serial.println(textChar);
      }
    }
  }
}
